def kingdoms():
    rows = [["🥇 金头（2:32）", "🦁 有鹰翅的狮子（7:4）", "—", ("k", "巴比伦"), "605–539", "“你就是那金头”（2:38）"],
            ["🥈 银的胸膛膀臂", "🐻 一边高的熊，口衔三根肋骨（7:5）", "🐏 双角公绵羊（8:20 明说“玛代和波斯王”）", ("k", "玛代—波斯"), "539–331", "一角高过另一角：波斯强于玛代"],
            ["🥉 铜的肚腹腰", "🐆 四翅四头的豹（7:6）", "🐐 公山羊的大角折断，长出四角（8:21 明说“希腊王”）", ("k", "希腊（亚历山大及其四分国）"), "331–63", "安提阿哥四世＝8章的“小角”"],
            ["⚙️ 铁腿、半铁半泥的脚", "🦖 第四兽，十角与“小角”（7:7-8）", "—", ("k", "罗马（改革宗传统读法）"), "63 → ", "铁“打碎克制百物”"],
            [("xr", "🪨 非人手凿出的石头（2:34-35,44）"), ("xr", "👤 驾云而来的“人子”（7:13-14）"), "—", ("xr", "神的国（基督的国度）"), ("xr", "罗马时代降临，永不败坏"), ("xr", "可1:15“日期满了，神的国近了”")]]
    return table(["2章 · 大像", "7章 · 四兽", "8章 · 羊", "国度", "年代（主前）", "说明"], rows)
def chiasm():
    rows = [["A 2章", "四国与神的国（大像）", "A′ 7章", "四国与神的国（四兽、人子）"], ["B 3章", "忠心者被救出火窑", "B′ 6章", "忠心者被救出狮子坑"], ["C 4章", "骄傲的王被降卑后悔改（尼布甲尼撒）", "C′ 5章", "骄傲的王被审判不悔改（伯沙撒）"]]
    return table(["", "亚兰文部分前半", "", "对应"], rows) + '<p class="sm">2:4下–7:28 用<b class="k">亚兰文</b>（当时国际通用语）写成，是给列国看的“世界史”；1章与8–12章用<b class="k">希伯来文</b>，是给神百姓的“家书”。</p>'
